#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.11"
# dependencies = ["pillow>=11,<13"]
# ///
"""Build one offline HTML deck from DECK.md and genuine local capture stills.
Run from any directory after frame_captures.py; PDF/review via export.cjs.
"""
import base64,io,re,subprocess,html,json
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[2];HERE=Path(__file__).parent
WORK=HERE/'review';WORK.mkdir(exist_ok=True)
def image(path,crop=None,width=1600):
 with Image.open(path) as src:
  im=src.convert('RGB');im=im.crop(crop) if crop else im
  im.thumbnail((width,1100));b=io.BytesIO();im.save(b,'JPEG',quality=87,optimize=True)
 return 'data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()
def capture(name,seconds,phone=False):
 p=WORK/(name+'.png');src=ROOT/'pitch/captures/mockups/clips'/name
 subprocess.run(['ffmpeg','-v','error','-y','-ss',str(seconds),'-i',str(src),'-frames:v','1','-update','1',str(p)],check=True)
 return image(p,(704,36,1216,1044) if phone else (180,16,1740,834),600 if phone else 1600)
def img(key,cls=''):return f'<img class="{cls}" src="{assets[key]}" alt="{html.escape(alts[key])}">'
assets={};alts={}
# Original pixel content comes exclusively from English recordings. All frame
# geometry is editorial. No API data or invented interface is used here.
specs={'station':('C3-wide-mockup.mp4',8,False),'phone':('B2-phone-mockup.mp4',3,True),'decision':('B1-phone-mockup.mp4',12,True),'pending':('B1-phone-mockup.mp4',12,True),'ground':('B1-ground-mockup.mp4',15,False),'map':('C6-map-mockup.mp4',8,False)}
for k,(name,t,phone) in specs.items():assets[k]=capture(name,t,phone);alts[k]='Real English ACORN '+k+' capture in an editorial device frame'
forest=ROOT/'pitch/photos/concept-illustration-station-medium-v2.png'
assets['forest']=image(forest,(0,120,900,820));alts['forest']='Illustration: forest crop from a generated concept image; no product evidence'
font=(ROOT/'placement/static/fonts/ibm-plex-sans-latin-400-normal.woff2').read_bytes();font64=base64.b64encode(font).decode()
font2=base64.b64encode((ROOT/'placement/static/fonts/ibm-plex-sans-latin-500-normal.woff2').read_bytes()).decode()
source=(ROOT/'pitch/DECK.md').read_text();sections=re.split(r'\n## (?=[1-9] ·)',source)[1:10];notes=[]
for i,section in enumerate(sections,1):
 n=re.search(r'\*\*Speaker notes:\*\* (.*?)(?=\n\n)',section,re.S);e=re.search(r'\*\*Evidence:\*\* (.*?)(?=\n\n|\Z)',section,re.S)
 notes.append({'slide':i,'title':section.splitlines()[0],'notes':n.group(1) if n else '', 'evidence':e.group(1) if e else ''})
(HERE/'NOTES.md').write_text('# ACORN — speaker notes\n\nNine slides / three minutes. Product stills: English laptop demo, recorded footage. Board measurements are separately sourced.\n\n'+'\n\n'.join(f"## {n['title']}\n\n{n['notes']}\n\nEvidence: {n['evidence']}" for n in notes)+'''\n\n## Credits and visual provenance

Forest images: generated concept-illustration-station-medium-v2.png, hardware-free crops; context only. Film shots 04/13 use concept-illustration-station-ridge.png and concept-illustration-occluding-ridge.png. DECK.md assigns neither picture to a slide; slide visuals remain as specified. No hardware photograph is supplied.
Product stills: 2026-11-14 English running-app recordings, fresh origin/main; own generic device frames. Phone arrival may also appear in the film as a separately credited Screeny export. See ../captures/README.md for capture provenance and chronology.
Smoke footage inside the interface: “Wildfire Near Monserrate”, Peter Angritt / Mrtony77 (2015), CC BY-SA 4.0, https://commons.wikimedia.org/wiki/File:Wildfire_Near_Monserrate.ogv. Fog: “Fog covering mountain time lapse”, Athulvis, CC BY-SA 4.0 (Commons external licence review pending), https://commons.wikimedia.org/wiki/File:Fog_covering_mountain_time_lapse.webm. Annotated/edited screenshots retain these credits; https://creativecommons.org/licenses/by-sa/4.0/.
Map: NLS Finland / Syke / Luke, CC BY 4.0. Model: Pyronear YOLO11s ONNX, AGPL-3.0; not trained by the team. Type: IBM Plex Sans, SIL OFL (OFL-IBM-Plex-Sans.txt).
''')
slides=[]
def add(body,cls=''):slides.append(f'<section class="slide {cls}" aria-label="Slide {len(slides)+1}"><header><span>ACORN</span><span>SCARABS / JUNCTION 2026</span></header>{body}<footer><span>Aerial Canopy Observation and Reporting Node</span><span>{len(slides)+1:02} / 09</span></footer></section>')
add(f'<div class="forest">{img("forest")}</div><div class="hero"><p class="kicker">SCARABS · JUNCTION 2026, HELSINKI</p><h1>ACORN</h1><h2>Earlier notice<br>starts here</h2><p>Aerial Canopy Observation<br>and Reporting Node</p></div><span class="ill">Illustration</span>','cover')
add(f'<div class="split"><div><p class="kicker">THE QUESTION</p><h2>Who can<br>keep watch?</h2><p class="lead">Goal: affordable observation<br>without an internet uplink</p><p class="muted">Cost and field benefit<br>not established</p></div><figure>{img("forest")}<figcaption>Illustration</figcaption></figure></div>')
add(f'<h2>A station that keeps<br>analysis local</h2><div class="architecture"><div class="flow"><b>Two USB cameras</b><i>↓</i><b>UNO Q Linux</b><i>↓</i><b class="amber">Smoke suspicion</b><p>MCU: local IR sensor<br>+ on-board status LED</p></div><figure>{img("station")}<figcaption>Laptop demo · recorded footage</figcaption></figure></div><p class="small bottom">Documented hardware architecture · assembly photograph still required</p>')
add(f'<h2>A person makes the call</h2><p class="lead">Smoke suspicion → evidence → operator decision</p><div class="review-pair"><figure>{img("phone")}<figcaption>Saved evidence</figcaption></figure><div class="call"><span class="amber">Smoke suspicion</span><h3>Confirm suspicion<br>/ Reject</h3><p>Separate states<br>of the same event</p><p class="muted">Laptop demo<br>· recorded footage</p></div><figure>{img("decision")}<figcaption>Decision controls</figcaption></figure></div>')
add(f'<h2>Send the suspicion, keep the imagery</h2><div class="proof-line"><div><strong>42-byte smoke alert</strong><br>packet v2 · no imagery over LoRa</div><div class="blue">LoRa transport<br>simulated today</div><div class="muted">Evidence: separate<br>close-range Wi-Fi</div></div><div class="packet"><figure class="packet-phone">{img("pending")}</figure><figure class="packet-ground">{img("ground")}</figure></div><p class="small bottom">Laptop demo · recorded footage · matching event, Wi-Fi demo off</p>')
add(f'<h2>Put the station where it can see</h2><div class="map-tags"><p>Real Finnish terrain and forest data</p><p>Compare sites · headings · camera pairs</p></div><figure class="map-shot">{img("map")}</figure><p class="blue map-caption">Simulated geometric visibility, not detection range</p><p class="small map-conditions">600 m height · 120 m grid · smoke + canopy · Haukilahti 180° · left+centre · 12 km model limit · 50 m target</p>')
add('<h2>Measured, simulated,<br>still open</h2><div class="evidence-rows"><div><span class="blue">MEASURED LIVE</span><h3>Dense daytime smoke filling the camera view</h3><p>UNO Q · centre crop · peak scores 0.62–0.76</p></div><div><span class="blue">SIMULATED</span><h3>LoRa transport · geometric coverage</h3></div><div><span class="amber">OPEN</span><h3>Field sensitivity · real radio · power endurance</h3></div></div><p class="small bottom">Screen replay · input 192 · threshold 0.35 · Center camera · 3 loops<br>Scores are not accuracy. Selected news footage failed; no field detection rate established.</p>')
add(f'<h2>Next proof:<br>a forest trial</h2><div class="next"><div><h3>Validate board sensitivity</h3><h3>Verify real radio<br>+ power endurance</h3><h3>Cost the complete station</h3><p class="blue">Seeking a supervised test setting</p></div><figure>{img("map")}<figcaption>Placement simulation · proposed work</figcaption></figure></div>')
add(f'<h2>Built for these challenges</h2><div class="closing"><div><p><span>Green European Renaissance</span><br>forest observation</p><p><span>Best use of Arduino UNO Q</span><br>Linux + MCU working together</p><p><span>Best Use of Codex</span><br>implementation, tests and board bring-up</p><h3 class="blue">Next: live demo</h3></div><figure>{img("station")}<figcaption>Laptop demo · recorded footage</figcaption></figure></div><p class="small bottom">Scarabs · Junction 2026, Helsinki</p>')
css=f'''@font-face{{font-family:Plex;src:url(data:font/woff2;base64,{font64})}}@font-face{{font-family:Plex;src:url(data:font/woff2;base64,{font2});font-weight:500}}
:root{{--bg:#090e13;--panel:#0f161d;--text:#e3e9ee;--muted:#a7b4bf;--blue:#8fc3e3;--amber:#f2a93b}}*{{box-sizing:border-box}}html,body{{margin:0;background:var(--bg);color:var(--text);font-family:Plex,sans-serif}}body{{overflow:hidden}}#stage{{position:absolute;left:50%;top:50%;transform-origin:center center;width:1920px;height:1080px}}.slide{{display:none;position:absolute;inset:0;padding:112px 96px 85px;background:var(--bg);overflow:hidden}}.slide.active{{display:block}}header,footer{{position:absolute;left:96px;right:96px;display:flex;justify-content:space-between;align-items:center}}header{{top:42px;font-size:24px;letter-spacing:.08em}}header span+span{{font-size:19px;color:var(--muted)}}footer{{bottom:30px;font-size:20px;color:var(--muted);border-top:1px solid #233140;padding-top:16px}}h1,h2,h3,p,figure{{margin:0}}h1{{font-size:150px;line-height:1.06;letter-spacing:.025em;font-weight:500}}h2{{font-size:68px;line-height:1.07;font-weight:500;letter-spacing:-.025em}}h3{{font-size:38px;line-height:1.2;font-weight:500}}p{{font-size:30px;line-height:1.4}}.lead{{margin-top:24px;font-size:34px}}.muted,figcaption{{color:var(--muted)}}.blue{{color:var(--blue)}}.amber{{color:var(--amber)}}figure img{{width:100%;height:100%;object-fit:contain}}figcaption{{font-size:23px;line-height:1.35;margin-top:12px}}.small{{font-size:24px;line-height:1.35;color:var(--muted)}}.bottom{{position:absolute;left:96px;bottom:100px}}.kicker{{font-size:23px;letter-spacing:.08em;color:var(--blue);margin-bottom:28px}}.forest{{position:absolute;inset:0}}.forest img{{width:100%;height:100%;object-fit:cover}}.forest:after{{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(9,14,19,.94),rgba(9,14,19,.56) 58%,rgba(9,14,19,.06))}}.hero{{position:relative;margin-top:100px}}.hero h2{{margin:24px 0 30px;font-size:82px}}.hero p:last-child{{color:var(--muted)}}.ill{{position:absolute;bottom:102px;right:96px;font-size:24px}}.split{{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;height:760px}}.split h2{{font-size:94px}}.split .muted{{margin-top:45px}}.split figure{{height:650px}}.split figure img{{object-fit:cover}}.architecture{{display:grid;grid-template-columns:430px 1fr;gap:54px;margin-top:30px;align-items:center}}.flow{{font-size:36px;text-align:center}}.flow b{{display:block;font-weight:500}}.flow i{{display:block;color:var(--blue);font-style:normal;margin:10px}}.flow p{{margin-top:35px;font-size:29px;color:var(--muted)}}.architecture figure{{height:530px}}.review-pair{{height:670px;display:grid;grid-template-columns:1fr 590px 1fr;gap:32px;margin:26px 80px 0}}.review-pair figure{{height:620px;text-align:center}}.call{{padding-top:145px;text-align:center}}.call>span{{font-size:30px}}.call h3{{margin:26px 0}}.call p{{margin-top:24px}}.proof-line{{display:flex;justify-content:space-between;font-size:28px;line-height:1.25;margin-top:28px}}.proof-line strong{{font-size:34px;font-weight:500}}.packet{{height:610px;position:relative;margin-top:18px}}.packet-phone{{position:absolute;left:0;top:0;width:310px;height:610px}}.packet-copy{{position:absolute;left:390px;top:8px}}.packet-copy p{{font-size:27px;margin-top:8px}}.packet-ground{{position:absolute;right:0;bottom:0;width:1320px;height:610px}}.map-tags{{display:flex;justify-content:space-between;margin-top:22px}}.map-tags p{{font-size:29px;color:var(--muted)}}.map-shot{{height:650px;margin-top:18px}}.map-caption{{position:absolute;bottom:130px;font-size:30px}}.map-conditions{{position:absolute;bottom:94px;font-size:21px}}.evidence-rows{{margin-top:45px}}.evidence-rows>div{{display:grid;grid-template-columns:320px 1fr;column-gap:26px;border-top:1px solid #33475a;padding:32px 0}}.evidence-rows span{{font-size:24px;letter-spacing:.06em;padding-top:9px}}.evidence-rows p{{grid-column:2;margin-top:10px;color:var(--muted)}}.next{{display:grid;grid-template-columns:740px 1fr;gap:45px;align-items:center;margin-top:40px}}.next h3{{margin-bottom:36px}}.next figure{{height:480px}}.next .blue{{font-size:31px;margin-top:48px}}.closing{{display:grid;grid-template-columns:870px 1fr;gap:30px;margin-top:58px;align-items:center}}.closing p{{font-size:29px;color:var(--muted);margin-bottom:30px}}.closing span{{font-size:34px;color:var(--text)}}.closing h3{{margin-top:45px}}.closing figure{{height:490px}}#help{{position:fixed;right:16px;bottom:5px;color:#a7b4bf;font-size:12px;opacity:0;transition:opacity .2s}}body:hover #help{{opacity:1}}#notes{{display:none;position:fixed;inset:0;background:var(--bg);padding:50px;overflow:auto;z-index:9}}#notes.open{{display:block}}#notes h2{{font-size:38px;margin-bottom:25px}}#notes p{{max-width:1100px;font-size:25px;margin:20px 0}}#notes button{{background:var(--panel);color:var(--text);border:1px solid #33475a;padding:12px;font:inherit}}@page{{size:1920px 1080px;margin:0}}@media print{{html,body{{width:1920px;overflow:visible;background:var(--bg);print-color-adjust:exact;-webkit-print-color-adjust:exact}}#stage{{position:static;transform:none!important;width:1920px;height:auto}}.slide{{position:relative;display:block!important;width:1920px;height:1080px;break-after:page}}#help,#notes{{display:none!important}}}}
'''
js='''const slides=[...document.querySelectorAll('.slide')];let current=Math.min(slides.length-1,Math.max(0,Number(location.hash.slice(1)||1)-1));const notesData=NOTES;function fit(){document.querySelector('#stage').style.transform=`translate(-50%,-50%) scale(${Math.min(innerWidth/1920,innerHeight/1080)})`;}function show(n){current=Math.min(slides.length-1,Math.max(0,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',i!==current)});history.replaceState(null,'','#'+(current+1));if(document.querySelector('#notes').classList.contains('open'))notes();}function notes(){const n=notesData[current];document.querySelector('#notes-body').textContent=n.notes;document.querySelector('#notes-evidence').textContent=n.evidence;document.querySelector('#notes-title').textContent=n.title;}document.addEventListener('keydown',e=>{if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(8);if(e.key.toLowerCase()==='f')document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();if(e.key.toLowerCase()==='n'){document.querySelector('#notes').classList.toggle('open');notes()}if(e.key==='Escape')document.querySelector('#notes').classList.remove('open')});document.querySelector('#close-notes').onclick=()=>document.querySelector('#notes').classList.remove('open');addEventListener('resize',fit);fit();show(current);'''.replace('NOTES',json.dumps(notes,ensure_ascii=False))
doc=f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ACORN · Scarabs · Junction 2026</title><style>{css}</style><body><main id="stage">{"".join(slides)}</main><div id="help">← → Navigate · F Full screen · N Notes</div><aside id="notes"><button id="close-notes">Close notes (N / Esc)</button><h2 id="notes-title"></h2><p id="notes-body"></p><p id="notes-evidence" class="muted"></p></aside><script>{js}</script></body></html>'
(HERE/'acorn-pitch.html').write_text(doc)
(HERE/'OFL-IBM-Plex-Sans.txt').write_text((ROOT/'placement/static/fonts/OFL-IBM-Plex-Sans.txt').read_text())
print('Built',HERE/'acorn-pitch.html',len(doc.encode()),'bytes')
